mapper.select:
select id, school_id, school_name, title, notice_code, notice_type, content, grade_ids, grade_names, team_meeting_id, purchase_process_id, start_time, end_time, purchase_start_time, purchase_end_time, status, apply_status, publish_time, result_publish_time, dept_id, create_by, create_time, update_by, update_time, remark, del_flag
from xfpt_group_notice
where id = #{id}

select g.id as id, g.id as notice_id, gns.supplier_id as supplier_id, g.school_id as school_id, coalesce(order_summary.school_name, g.school_name) as school_name, coalesce(order_summary.class_name, '-') as class_name, coalesce(order_summary.order_no, '-') as order_no, coalesce(order_summary.order_quantity, 0) as order_quantity, case when notice_delivery.has_shipped = 1 then '4' when production.has_finished = 1 then '3' when production.has_in_production = 1 then '2' when coalesce(order_summary.has_supplier_viewed, 0) = 1 then '1' else '0' end as progress_status, case when notice_delivery.has_shipped = 1 then '已发货' when production.has_finished = 1 then '已完成' when production.has_in_production = 1 then '制作中' when coalesce(order_summary.has_supplier_viewed, 0) = 1 then '供应商已查看' else '待查看' end as progress_status_name, notice_delivery.logistics_no as logistics_no, production.production_no as production_no, notice_delivery.delivery_no as delivery_no, g.title as notice_name, gns.supplier_name as manufacturer_name, coalesce(order_summary.latest_create_time, production.latest_create_time, notice_delivery.latest_create_time, g.create_time) as create_time from xfpt_group_notice g inner join xfpt_group_notice_supplier gns on gns.notice_id = g.id and gns.del_flag = '0' left join (
) order_summary on order_summary.notice_id = g.id and order_summary.school_id = g.school_id and order_summary.supplier_id = gns.supplier_id left join ( select notice_id, school_id, supplier_id, max(case when status = '1' then 1 else 0 end) as has_in_production, max(case when status in ('2', '3') then 1 else 0 end) as has_finished, substring_index(group_concat(production_no order by id desc separator ','), ',', 1) as production_no, max(create_time) as latest_create_time from xfpt_production_order where del_flag = 0 and order_type = '1' and notice_id is not null group by notice_id, school_id, supplier_id ) production on production.notice_id = g.id and production.school_id = g.school_id and production.supplier_id = gns.supplier_id left join (
) notice_delivery on notice_delivery.notice_id = g.id and notice_delivery.school_id = g.school_id and notice_delivery.supplier_id = gns.supplier_id where g.del_flag = 0 and g.notice_type = '1'
and g.school_id = #{schoolId}
and g.dept_id = #{deptId}
and order_summary.class_name like concat('%', #{className}, '%')
and order_summary.order_no like concat('%', #{orderNo}, '%')
and ( case when notice_delivery.has_shipped = 1 then '4' when production.has_finished = 1 then '3' when production.has_in_production = 1 then '2' when coalesce(order_summary.has_supplier_viewed, 0) = 1 then '1' else '0' end ) = #{progressStatus}
order by coalesce(order_summary.latest_create_time, production.latest_create_time, notice_delivery.latest_create_time, g.create_time) desc, g.id desc

select * from ( select g.id as id, g.id as notice_id, o.supplier_id as supplier_id, g.title as notice_name, o.supplier_name as manufacturer_name, coalesce(s.promotion_count, 0) as promotion_count, coalesce(i.expected_sales_count, 0) as expected_sales_count, coalesce(o.order_count, 0) as order_count, case when coalesce(i.expected_sales_count, 0) = 0 then 0 else round(coalesce(o.order_count, 0) * 100 / i.expected_sales_count, 2) end as order_rate, concat(date_format(g.start_time, '%Y-%m-%d'), ' ~ ', date_format(g.end_time, '%Y-%m-%d')) as time_range, case when g.end_time is null then '' when g.end_time < now() then '已截止' else concat(timestampdiff(day, now(), g.end_time), '天') end as remain_time from xfpt_group_notice g left join ( select notice_id, sum(coalesce(buy_num, 0)) as expected_sales_count from xfpt_group_notice_item where del_flag = 0 group by notice_id ) i on i.notice_id = g.id left join ( select notice_id, supplier_id, supplier_name, count(distinct coalesce(student_id, user_id, id)) as order_count from xfpt_order_info where del_flag = 0 and order_type = '1' and (order_status is null or order_status != '5') group by notice_id, supplier_id, supplier_name ) o on o.notice_id = g.id left join ( select shcool_id, count(1) as promotion_count from xfpt_student_info where del_flag = 0 group by shcool_id ) s on s.shcool_id = cast(g.school_id as char) where g.del_flag = 0 and g.school_id = #{schoolId} and g.dept_id = #{deptId}
and o.supplier_name like concat('%', #{manufacturerName}, '%')
and g.end_time >= #{startTime}
and g.end_time <= #{endTime}
and g.end_time >= now() and g.end_time <= date_add(now(), interval 7 day)
and g.end_time >= now() and g.end_time <= date_add(now(), interval 1 month)
and g.end_time >= now() and g.end_time <= date_add(now(), interval 3 month)
) p where 1 = 1
and p.order_rate >= #{orderRateMin}
and p.order_rate <= #{orderRateMax}
order by p.notice_id desc

select item.goods_name as product_name, item.unit_price as price, item.buy_num as quantity, coalesce(info.student_name, info.user_name) as order_person, info.create_time as order_time from xfpt_order_info info inner join xfpt_order_item item on item.order_id = info.id and item.del_flag = 0 where info.del_flag = 0 and info.notice_id = #{noticeId} and info.order_type = '1' and (info.order_status is null or info.order_status != '5')
and info.school_id = #{schoolId}
and info.dept_id = #{deptId}
and info.supplier_id = #{supplierId}
order by info.create_time desc, info.id desc

mapper.update:
update xfpt_group_notice
school_id = #{schoolId}, school_name = #{schoolName}, title = #{title}, notice_code = #{noticeCode}, notice_type = #{noticeType}, content = #{content}, grade_ids = #{gradeIds}, grade_names = #{gradeNames}, team_meeting_id = #{teamMeetingId}, purchase_process_id = #{purchaseProcessId}, start_time = #{startTime}, end_time = #{endTime}, status = #{status}, apply_status = #{applyStatus}, publish_time = #{publishTime}, result_publish_time = #{resultPublishTime}, dept_id = #{deptId}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark}, del_flag = #{delFlag},
where id = #{id}

